// Allow warnings generated by PyO3 macros
#![allow(non_local_definitions)]

use pyo3::prelude::*;

// Module declarations
mod api;
mod async_client;
mod auth;
mod batch; // ULTRA-OPTIMIZED: Batch request processing for A级 performance
mod client;
mod config;
pub mod connection_pool; // High-performance connection pool implementation
mod core;
mod error;
mod gil_optimized; // ULTRA-OPTIMIZED: Deep GIL optimization for A级 performance
mod hooks;
mod hyper_client; // New hyper-based client module
mod ureq_client; // Ureq-based synchronous client module
mod memory_pool; // EXTREME performance memory pool for A级 optimization  
mod models;
mod precompiled; // ULTRA-OPTIMIZED: Precompiled HTTP methods and headers for A级 performance
mod proxy_config_stub; // Temporary stub for proxy configuration
mod request;
mod response;
mod runtime;
mod ssl_config_stub; // Temporary stub for SSL configuration
mod streaming_stub; // Temporary stub for streaming functionality
mod sync_core; // Synchronous HTTP client implementation
mod transport; // Transport implementations including MockTransport
mod transport_stub; // Temporary stub for transport configuration
mod utils;
mod zero_copy; // ULTRA-OPTIMIZED: Zero-copy data transfer for A级 performance

// Re-export main types and functions
pub use auth::*;
pub use error::*;
pub use request::HttpRequest;
pub use response::HttpResponse;
// StreamingHttpResponse and StreamingClient removed - httpx doesn't have these classes
pub use async_client::AsyncHttpClient;
pub use client::HttpClient;
pub use config::ClientConfig;
pub use sync_core::SyncHttpClient;
// Re-export API functions (request function is available via Python module, not Rust re-export)
pub use api::{delete, get, head, options, patch, post, put, stream};
pub use hooks::EventHooksProxy;
pub use models::{
    HttpBasicAuth, HttpCookies, HttpCookiesIterator, HttpDigestAuth, HttpHeaders, HttpHeadersIterator, HttpLimits, HttpNetRCAuth,
    HttpQueryParams, HttpTimeout, HttpUrl,
};


// Python module definition
#[pymodule]
fn _core(py: Python, m: &PyModule) -> PyResult<()> {
    // Initialize Rustls CryptoProvider to avoid runtime panics
    std::sync::Once::new().call_once(|| {
        rustls::crypto::aws_lc_rs::default_provider()
            .install_default()
            .ok();
    });

    // Add classes (httpx-compatible only)
    m.add_class::<HttpRequest>()?;
    m.add_class::<HttpResponse>()?;
    m.add_class::<HttpClient>()?;
    m.add_class::<AsyncHttpClient>()?;
    m.add_class::<SyncHttpClient>()?;

    // Add data model classes
    m.add_class::<HttpHeaders>()?;
    m.add_class::<HttpHeadersIterator>()?;
    m.add_class::<HttpQueryParams>()?;
    m.add_class::<HttpCookies>()?;
    m.add_class::<HttpCookiesIterator>()?;
    m.add_class::<HttpUrl>()?;
    m.add_class::<HttpTimeout>()?;
    m.add_class::<HttpLimits>()?;
    m.add_class::<HttpBasicAuth>()?;
    m.add_class::<HttpDigestAuth>()?;
    m.add_class::<HttpNetRCAuth>()?;

    // Add hooks proxy class
    m.add_class::<EventHooksProxy>()?;

    // Transport classes temporarily disabled during hyper migration
    // m.add_class::<transport::FasterhttpTransport>()?;
    m.add_class::<transport::MockTransport>()?;
    // m.add_class::<transport::HTTPSRedirectTransport>()?;

    // Add API functions
    m.add_function(wrap_pyfunction!(api::get, m)?)?;
    m.add_function(wrap_pyfunction!(api::post, m)?)?;
    m.add_function(wrap_pyfunction!(api::put, m)?)?;
    m.add_function(wrap_pyfunction!(api::patch, m)?)?;
    m.add_function(wrap_pyfunction!(api::delete, m)?)?;
    m.add_function(wrap_pyfunction!(api::head, m)?)?;
    m.add_function(wrap_pyfunction!(api::options, m)?)?;
    m.add_function(wrap_pyfunction!(api::request, m)?)?;
    m.add_function(wrap_pyfunction!(api::stream, m)?)?;

    // Add ULTRA-OPTIMIZED batch processing functions for A级 performance
    m.add_function(wrap_pyfunction!(batch::batch_request, m)?)?;
    m.add_class::<batch::SmartBatcher>()?;

    // Add ULTRA-OPTIMIZED zero-copy utilities for A级 performance
    m.add_class::<zero_copy::ZeroCopyUtils>()?;

    // Add ULTRA-OPTIMIZED GIL-free processing for A级 performance
    m.add_function(wrap_pyfunction!(gil_optimized::gil_optimized_request, m)?)?;
    m.add_function(wrap_pyfunction!(gil_optimized::gil_optimized_async_request, m)?)?;
    m.add_function(wrap_pyfunction!(gil_optimized::gil_optimized_batch_request, m)?)?;

    // Add exception factory functions
    m.add_function(wrap_pyfunction!(error::new_http_status_error, m)?)?;

    // Add exception types (httpx-compatible only)
    m.add("HTTPError", py.get_type::<HTTPError>())?;

    // Network exceptions
    m.add("NetworkError", py.get_type::<NetworkError>())?;
    
    // Connection exceptions
    m.add("ConnectError", py.get_type::<ConnectError>())?;
    m.add("ConnectTimeout", py.get_type::<ConnectTimeout>())?;

    // SSL exceptions
    m.add("SSLError", py.get_type::<SSLError>())?;

    // Timeout exceptions
    m.add("TimeoutException", py.get_type::<TimeoutException>())?;
    m.add("ReadTimeout", py.get_type::<ReadTimeout>())?;
    m.add("WriteTimeout", py.get_type::<WriteTimeout>())?;
    m.add("PoolTimeout", py.get_type::<PoolTimeout>())?;

    // Request/Response exceptions
    m.add("RequestError", py.get_type::<RequestError>())?;

    // HTTP Status exceptions
    m.add("HTTPStatusError", py.get_type::<HTTPStatusError>())?;

    // Stream exceptions
    m.add("StreamError", py.get_type::<StreamError>())?;

    // Protocol exceptions
    m.add("ProtocolError", py.get_type::<ProtocolError>())?;
    m.add("TooManyRedirects", py.get_type::<TooManyRedirects>())?;

    // Transport exceptions
    m.add("TransportError", py.get_type::<TransportError>())?;

    // Additional httpx-compatible exceptions
    m.add("InvalidURL", py.get_type::<InvalidURL>())?;
    m.add("LocalProtocolError", py.get_type::<LocalProtocolError>())?;
    m.add("RemoteProtocolError", py.get_type::<RemoteProtocolError>())?;
    m.add("ReadError", py.get_type::<ReadError>())?;
    m.add("WriteError", py.get_type::<WriteError>())?;
    m.add("UnsupportedProtocol", py.get_type::<UnsupportedProtocol>())?;

    // Missing httpx-compatible exceptions
    m.add("NetworkError", py.get_type::<NetworkError>())?;
    m.add("ProxyError", py.get_type::<ProxyError>())?;
    m.add("DecodingError", py.get_type::<DecodingError>())?;
    m.add("CookieConflict", py.get_type::<CookieConflict>())?;
    m.add("CloseError", py.get_type::<CloseError>())?;
    m.add("RequestNotRead", py.get_type::<RequestNotRead>())?;
    m.add("ResponseNotRead", py.get_type::<ResponseNotRead>())?;
    m.add("StreamClosed", py.get_type::<StreamClosed>())?;
    m.add("StreamConsumed", py.get_type::<StreamConsumed>())?;

    Ok(())
}
